select  from dm_alarm_event

    task_id = #{taskId}

        and source_name = #{sourceCode}




        and (
            source_name like #{keywordPattern}


                or source_name in

                    #{sourceValue}


            or alarm_msg like #{keywordPattern}
            or task_name like #{keywordPattern}
            or channel_code like #{keywordPattern}
            or trigger_rule like #{keywordPattern}
            or parameter_name like #{keywordPattern}
            or tm_symbol like #{keywordPattern}
            or alarm_detail like #{keywordPattern}
        )


        and alarm_level = #{alarmLevel}


        and alarm_status = #{alarmStatus}


        and alarm_time >= #{startTime}


        and alarm_time <= #{endTime}

    and is_deleted = 0

order by alarm_time desc, id desc

mapper.update:
update dm_alarm_event set recover_time = #{recoverTime}, update_time = current_timestamp
where dedup_key = #{dedupKey} and is_deleted = 0 and recover_time is null
  and last_trigger_time <= #{recoverTime}
